        AND create_user = #{query.ownerUserId}


        AND biz_type = #{query.bizType}


        AND biz_id = #{query.bizId}


        AND content_type LIKE CONCAT(#{query.contentType}, '%')


        AND original_name LIKE CONCAT('%', #{query.originalName}, '%')


        AND create_time  >=  #{query.startTime}
        AND create_time  <=  #{query.endTime}


ORDER BY
    create_time DESC

